(3425543, 475215, 38032, '<td valign="top">I like the color and contrast and such - the face looks just a hint insincere but it''s definitely a great piece.</td>', 'I like the color and contrast and such - the face looks just a hint insincere but it''s definitely a great piece.', '2007-03-03 13:26:50.000000', NULL, 1),
(3425544, 471936, 38032, '<td valign="top">Nice lighting and treatment</td>', 'Nice lighting and treatment', '2007-03-03 13:27:25.000000', NULL, 1),
(3425545, 475081, 38032, '<td valign="top">The hues and tones are excellent here.  The composition is not working for me though - I think the blank card dominates the image and the heart thingy is .. well what is it? - If the card was more diagonal and the flower more predominatnt and the heart taken out you have a much better shot IMO.</td>', 'The hues and tones are excellent here.  The composition is not working for me though - I think the blank card dominates the image and the heart thingy is .. well what is it? - If the card was more diagonal and the flower more predominatnt and the heart taken out you have a much better shot IMO.', '2007-03-03 13:30:34.000000', NULL, 1),
(3425547, 475322, 38032, '<td valign="top">That''s a beaut for sure ... I''m guessing we''re talkin'' South Beach FL?  ... Oh boy, I''ll be in Key west next week - can''t wait.  Beautiful contrast and colors BTW.</td>', 'That''s a beaut for sure ... I''m guessing we''re talkin'' South Beach FL?  ... Oh boy, I''ll be in Key west next week - can''t wait.  Beautiful contrast and colors BTW.', '2007-03-03 13:31:43.000000', NULL, 1),
(3425549, 474695, 38032, '<td valign="top">That works well but ironically could use just a bit more info or drama  IMO.</td>', 'That works well but ironically could use just a bit more info or drama  IMO.', '2007-03-03 13:32:33.000000', NULL, 1),
(3425553, 474739, 38032, '<td valign="top">Great light and a beautiful nature pic.  The focus seems a bit soft on the middle -  like fresh-baked cookies ... well not really, kinda like almost perfect but just  a bit more in the oven ;P</td>', 'Great light and a beautiful nature pic.  The focus seems a bit soft on the middle -  like fresh-baked cookies ... well not really, kinda like almost perfect but just  a bit more in the oven ;P', '2007-03-03 13:34:36.000000', NULL, 1),
(3425584, 475370, 30049, '<td valign="top">This is a wonderful image as far as clarity/sharpness, composition, and interest.  Regarding the acronym, I would have connected it somewhat to your photo.  Bummer you had to forego letting the image speak for itself and describe your acronym in the title.</td>', 'This is a wonderful image as far as clarity/sharpness, composition, and interest.  Regarding the acronym, I would have connected it somewhat to your photo.  Bummer you had to forego letting the image speak for itself and describe your acronym in the title.', '2007-03-03 13:55:25.000000', NULL, 1),
(3425588, 474859, 30049, '<td valign="top">Funny how the mind plays tricks with words/letter combinations.  When I first saw your acronym I thought it was RSVP.  As for your image, I think the aspect ration works fine for this.  The details aren''t quite there (soft focus on the birds), and it''s a little noisy/grainy.  Really not sure what the acronym is (probably something made up), but I can hazard a couple of guesses mentally.  Overall, an OK job - good luck in the challenge.</td>', 'Funny how the mind plays tricks with words/letter combinations.  When I first saw your acronym I thought it was RSVP.  As for your image, I think the aspect ration works fine for this.  The details aren''t quite there (soft focus on the birds), and it''s a little noisy/grainy.  Really not sure what the acronym is (probably something made up), but I can hazard a couple of guesses mentally.  Overall, an OK job - good luck in the challenge.', '2007-03-03 13:58:52.000000', NULL, 1),
(3425590, 474441, 30049, '<td valign="top">Considering the weather and location, your choice of B/W is a good one.  Nice job of working the sky to enhance the gloomy look.  Acronym is a bit on the easy side, but you did fine with the image part of it.  BTW, it is legal to clone out dust spots.  :D  Good luck in the challenge.</td>', 'Considering the weather and location, your choice of B/W is a good one.  Nice job of working the sky to enhance the gloomy look.  Acronym is a bit on the easy side, but you did fine with the image part of it.  BTW, it is legal to clone out dust spots.  :D  Good luck in the challenge.', '2007-03-03 14:01:18.000000', NULL, 1),
(3425593, 473648, 30049, '<td valign="top">Wonderfully meets the acronym - good for a laugh.  If this didn''t have a minor problem with blurriness it''d get a 10 from me.  As is, it''s still good for a 7.  Best of luck to you in the challenge.</td>', 'Wonderfully meets the acronym - good for a laugh.  If this didn''t have a minor problem with blurriness it''d get a 10 from me.  As is, it''s still good for a 7.  Best of luck to you in the challenge.', '2007-03-03 14:02:48.000000', NULL, 1),
(3425641, 475266, 30982, '<td valign="top">I''m not sure what the acronym is but it''s interesting that they died so close together.  Not unusual if they were married a long time, though.  The picture itself is a bit plain - centered and shot from above.  If this has meaning to you, maybe try shooting it from a bit lower and include some of the environment.</td>', 'I''m not sure what the acronym is but it''s interesting that they died so close together.  Not unusual if they were married a long time, though.  The picture itself is a bit plain - centered and shot from above.  If this has meaning to you, maybe try shooting it from a bit lower and include some of the environment.', '2007-03-03 14:30:43.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3425643, 474948, 30982, '<td valign="top">I should know what the acronym is, but suffice it to say I know it has to do with computers.  I like the DOF and the resulting bokeh - nice shot!</td>', 'I should know what the acronym is, but suffice it to say I know it has to do with computers.  I like the DOF and the resulting bokeh - nice shot!', '2007-03-03 14:31:19.000000', NULL, 1),
(3425646, 474756, 30982, '<td valign="top">Meets the challenge!  The background and shadows from the lighting give this a sort of "snapshot" kind of feel, which isn''t necessarily a bad thing but doesn''t go over well as far as DPC in most cases.</td>', 'Meets the challenge!  The background and shadows from the lighting give this a sort of "snapshot" kind of feel, which isn''t necessarily a bad thing but doesn''t go over well as far as DPC in most cases.', '2007-03-03 14:32:22.000000', NULL, 1),
(3425647, 471932, 30982, '<td valign="top">No idea what the acronym is but I love the picture!</td>', 'No idea what the acronym is but I love the picture!', '2007-03-03 14:32:42.000000', NULL, 1),
(3425649, 475308, 30982, '<td valign="top">I really like the composition - black and white suits this well, too.</td>', 'I really like the composition - black and white suits this well, too.', '2007-03-03 14:33:13.000000', NULL, 1),
(3425653, 474923, 30982, '<td valign="top">Good acronym - didn''t know that''s what it stood for.  (I''ve always heard "Gentlemen Only, Ladies Forbidden".)  The spotlight effect highlights your subject well and I like the angle of the club coming into the shot.  Probably not WOW enough for a high DPC vote but a nicely done take on the challenge.</td>', 'Good acronym - didn''t know that''s what it stood for.  (I''ve always heard "Gentlemen Only, Ladies Forbidden".)  The spotlight effect highlights your subject well and I like the angle of the club coming into the shot.  Probably not WOW enough for a high DPC vote but a nicely done take on the challenge.', '2007-03-03 14:34:40.000000', NULL, 1),
(3425667, 474842, 30982, '<td valign="top">Depicts your acronym quite nicely!  I like the fuzzy stuff - adds even more credence to the acronym, since it kinda represents the paths data takes.</td>', 'Depicts your acronym quite nicely!  I like the fuzzy stuff - adds even more credence to the acronym, since it kinda represents the paths data takes.', '2007-03-03 14:42:55.000000', NULL, 1),
(3425668, 475075, 30982, '<td valign="top">Very good action shot with good clarity on the center figures and good DOF to blur the background.  Could use some white balance, though - if you work in RAW you can correct it there.  If not, you can correct using color tools to remove the yellow.</td>', 'Very good action shot with good clarity on the center figures and good DOF to blur the background.  Could use some white balance, though - if you work in RAW you can correct it there.  If not, you can correct using color tools to remove the yellow.', '2007-03-03 14:43:57.000000', NULL, 1),
(3425670, 475169, 30982, '<td valign="top">I''m not entirely sure, but I don''t think that''s how it''s supposed to be installed...  :)</td>', 'I''m not entirely sure, but I don''t think that''s how it''s supposed to be installed...  :)', '2007-03-03 14:44:26.000000', NULL, 1),
(3425675, 475084, 30982, '<td valign="top">Not sure what the acronym is.  It appears as though the tower is leaning ever so slightly to the right.  Nice sky!</td>', 'Not sure what the acronym is.  It appears as though the tower is leaning ever so slightly to the right.  Nice sky!', '2007-03-03 14:45:02.000000', NULL, 1),
(3425677, 475079, 30982, '<td valign="top">Quite clever.  I like it.</td>', 'Quite clever.  I like it.', '2007-03-03 14:45:18.000000', NULL, 1),
